#!/bin/sh
# Static launcher, regenerated by dispatch.ps1 on every START and mounted read-only.
# Reads the task from the mounted file so the task text never crosses an argv boundary (docs/04).
exec claude -p "$(cat /run/task.txt)" --model "$WORK_MODEL" --effort "$WORK_EFFORT" --continue --permission-mode dontAsk --settings /etc/claude-settings.json --add-dir /mem-project --add-dir /mem-root --add-dir /mem-shared
